const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  BorderStyle, ShadingType, Table, TableRow, TableCell, WidthType,
  PageBreak, LevelFormat
} = require('docx');
const fs = require('fs');

// Color palette
const C = {
  RED: "C0392B",
  GOLD: "D4A017",
  DARK: "2C3E50",
  BLUE: "1A5276",
  GREEN: "1E8449",
  GRAY: "7F8C8D",
  LIGHT: "EBF5FB",
  LIGHTGOLD: "FEF9E7",
  LIGHTGREEN: "EAFAF1",
  LIGHTGRAY: "F2F3F4",
};

function heading1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 400, after: 200 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: C.RED, space: 4 } },
    children: [new TextRun({ text, bold: true, size: 36, color: C.RED, font: "Arial" })]
  });
}

function heading2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 280, after: 140 },
    children: [new TextRun({ text, bold: true, size: 28, color: C.BLUE, font: "Arial" })]
  });
}

function heading3(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_3,
    spacing: { before: 200, after: 100 },
    children: [new TextRun({ text: `◆ ${text}`, bold: true, size: 24, color: C.GREEN, font: "Arial" })]
  });
}

function body(text, opts = {}) {
  return new Paragraph({
    spacing: { before: 80, after: 80 },
    children: [new TextRun({ text, size: 22, font: "Arial", ...opts })]
  });
}

function tip(label, text) {
  return new Paragraph({
    spacing: { before: 60, after: 60 },
    indent: { left: 360 },
    children: [
      new TextRun({ text: `${label}：`, bold: true, size: 21, color: C.GOLD, font: "Arial" }),
      new TextRun({ text, size: 21, font: "Arial" })
    ]
  });
}

function bullet(text) {
  return new Paragraph({
    spacing: { before: 40, after: 40 },
    indent: { left: 480, hanging: 240 },
    children: [new TextRun({ text: `• ${text}`, size: 21, font: "Arial" })]
  });
}

function sectionDivider() {
  return new Paragraph({
    spacing: { before: 200, after: 200 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 2, color: "CCCCCC", space: 2 } },
    children: []
  });
}

function infoBox(title, lines, color = C.LIGHT) {
  const cellBorder = { style: BorderStyle.SINGLE, size: 2, color: "B8CCE4" };
  const borders = { top: cellBorder, bottom: cellBorder, left: cellBorder, right: cellBorder };
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({
        children: [new TableCell({
          borders,
          shading: { fill: color.replace('#',''), type: ShadingType.CLEAR },
          margins: { top: 120, bottom: 120, left: 200, right: 200 },
          children: [
            new Paragraph({ children: [new TextRun({ text: `📌 ${title}`, bold: true, size: 22, color: C.BLUE, font: "Arial" })] }),
            ...lines.map(l => new Paragraph({ spacing: {before:40,after:40}, children: [new TextRun({ text: l, size: 20, font: "Arial" })] }))
          ]
        })]
      })
    ]
  });
}

