        spots: [
          { name: "故宫（紫禁城）", detail: "世界上现存规模最大、保存最完整的木质结构古建筑群，明清两代皇宫，占地72万平方米。推荐上午早到，避开人流。" },
          { name: "长城（八达岭/慕田峪）", detail: "中华民族精神象征，八达岭是最知名路段，慕田峪相对较少拥挤且保存完好，风景更为秀丽。" },
          { name: "天坛", detail: "明清两代帝王祭天、祈谷的场所，建于1420年，是世界上现存规模最大、保存最完好的祭天建筑群。" },
